entries[168289] = { ["name"] = "Archaeology Template Spell", ["text"] = "Wirken in 2 sek.\nObwohl die Mantis Windwolle und kaiserliche Seide verwenden, ist ihr bevorzugtes Material eine Art von \"Gewebe\", das aus den Flügeln verschiedener insektoider Kreaturen geschaffen wird – einschließlich ihrer eigenen. Dieses Banner ist ein Beispiel." }
entries[168290] = { ["name"] = "Frostwolfaxt mit Bissspuren", ["text"] = "Wirken in 2 sek. 5\nUm als vollwertiges Mitglied des Frostwolfklans anerkannt zu werden, muss jedes Mitglied des Klans allein in die Wildnis ziehen und Bande zu einem wilden Frostwolf knüpfen. Nicht alle Mitglieder des Klans bestehen diese Prüfung, doch jene, denen es gelingt, gewinnen dabei einen Begleiter, der ihnen ein Leben lang treu ist." }
entries[168291] = { ["name"] = "Ahnenschnitzereien des Frostwolfklans", ["text"] = "Wirken in 2 sek. 5\nAls Teil des Übergangsritus zum Erwachsenendasein muss ein Frostwolf einen Frosteber töten und so viel vom Stammbaum seiner Familie in den größten Hauer der Kreatur einritzen, wie darauf Platz findet. Familiengeschichte und Tradition werden beim Frostwolfklan groß geschrieben, daher werden in jeder Jahreszeit die größten Frosteber gejagt, um die Erinnerung an die Ahnen des Klans bewahren zu können." }
entries[168292] = { ["name"] = "Wolfspelzschneeschuhe", ["text"] = "Wirken in 2 sek. 5\nDa die eisige Frostwindwüste ihnen nur wenig Möglichkeiten zu einer pflanzlichen Ernährung bietet, sind die Frostwölfe bei der Suche nach Nahrung auf ihre Jäger angewiesen. Diese Schneeschuhe, die aus Wolfsknochen und Pelzen gefertigt wurden, verhindern, dass ihr Träger bei der Jagd nach Beute in die tiefen Schneewehen einsinkt." }
entries[168293] = { ["name"] = "Trommeln des Kriegssängers", ["text"] = "Wirken in 2 sek. 5\nDer Kriegshymnenklan nutzt Methoden der Einschüchterung, um seine Feinde zu überwältigen, und hat sich seinen Namen durch seine markerschütternden Schlachtrufe und dröhnenden Trommelmärsche verdient. Diese makaberen Trommeln wurden aus Talbukleder angefertigt, das allem Anschein nach fest über den Schädel eines Ogers gezogen wurde. Damit feiert der Klan seine Unabhängigkeit vom Imperium der Oger." }
entries[168294] = { ["name"] = "Kreischendes Schwirrholz", ["text"] = "Wirken in 2 sek. 5\nEin Schwirrholz ist ein armlanges Stück aus unbiegsamem Holz, das am Ende eines langen Seils befestigt ist und das sein Träger über dem Kopf kreisen lässt. Dabei entsteht ein dröhnender Lärm, der noch in weiter Ferne zu hören ist. Dieses Exemplar wurde vom Kriegshymnenklan auf eine Weise ausgehöhlt, dass anstelle des von den meisten anderen Klans bevorzugten tiefen Brummens ein schrilles Pfeifen erzeugt wird." }
entries[168295] = { ["name"] = "Zeremonienpike des Kriegshymnenklans", ["text"] = "Wirken in 2 sek. 5\nDie Reiter des Kriegshymnenklans sind immer in Bewegung. Im Lager wird das Zelt einer Familie mit einer langen, in den Boden gerammten Pike markiert, die oftmals mit den Schädeln besiegter Feinde verziert ist. Dieses Exemplar ist über hundert Jahre alt und in ihren Schaft wurden die Namen mehrerer wichtiger Schlachten hineingebrannt." }
entries[168296] = { ["name"] = "Metallurgenhammer", ["text"] = "Wirken in 2 sek. 5\nTrotz zahlreicher Dellen und Kratzer kann man die in diesen einstmals stolzen Hammer eingeätzte Ikonografie des Schwarzfelsklans noch gut erkennen. Der Schwarzfelsklan war der erste Orcklan, dem es gelang, das Metall gleichen Namens zu schmieden, und sie bevorzugen im Kampf stumpfe Waffen, um ihre Ahnen zu ehren." }
entries[168297] = { ["name"] = "Elementarblasebalg", ["text"] = "Wirken in 2 sek. 5\nDer Schwarzfelsklan nutzte ursprünglich die natürlich vorkommenden und von Elementaren befeuerten Infernos des uralten Draenor, um das nach ihnen benannte Erz zu formen und zu härten. Ein Schamane könnte mit diesem Blasebalg die Macht eines Feuergeists direkt in einen Schmelzofen kanalisieren, was es dem Schwarzfelsklan ermöglicht, praktisch überall Schmieden zu errichten." }
entries[168298] = { ["name"] = "Rasiermesser des Schwarzfelsklans", ["text"] = "Wirken in 2 sek. 5\nMännliche Orcs des Schwarzfelsklans schneiden sich nie die Haare, bis sie das Erwachsenenalter erreichen. Dann wird ihr Kopf rasiert und ihre Rolle in dieser ausgesprochen reglementierten Gesellschaft festgelegt. Dieses uralte Schnappmesser wurde aus Schwarzfelserz geschmiedet und ist mit Edelsteinen verziert. Wahrscheinlich wurde es viele Generationen lang von einer bedeutenden Familie für Initiationsrituale genutzt." }
entries[168299] = { ["name"] = "Beschwertes Hackebeil", ["text"] = "Wirken in 2 sek. 5\nDie Krieger des Klans der Zerschmetterten Hand nehmen ihren Klannamen wörtlich und zertrümmern sich in einem Ritual die Hand, bevor sie sie abschneiden. Der Stumpf wird ausgebrannt und durch eine Waffe unterschiedlichster Art ersetzt. Diese Klinge, die einem einfachen Fleischerbeil ähnelt, wurde stark beschwert, um einen einzelnen sauberen Schnitt am Handgelenk zu erleichtern." }
entries[168300] = { ["name"] = "Hakendolch", ["text"] = "Wirken in 2 sek. 5\nDer Klan der Zerschmetterten Hand feiert seinen Sieg in der Schlacht durch Selbstverstümmelung. Die berühmtesten Krieger des Klans sind über und über mit Piercings und Narben bedeckt. Mit zunehmendem Alter ist es immer schwerer zu erkennen, welche davon dem siegreichen Orc von Feinden zugefügt wurden und welche von ihm selbst." }
entries[168301] = { ["name"] = "Gezackter Angelhaken", ["text"] = "Wirken in 2 sek. 5\nDieses armlange Widerhakennest hat wenig mit einem gewöhnlichen Angelhaken gemeinsam, sondern ähnelt eher einer Hellebarde. Man kann sich ungefähr vorstellen, was für riesige Leviathane mit so einem Haken gefangen werden könnten. Kein Wunder also, dass die meisten Orcs die Jagd von Land aus bevorzugen." }
entries[168302] = { ["name"] = "Verkalktes eingemachtes Auge", ["text"] = "Wirken in 2 sek. 5\nDieses wohlerhaltene Auge muss einem Häuptling des Klans des Blutenden Auges gehört haben. Beim Aufstieg zum Häuptling des Klans muss dieser eine schamanische Visionsreise antreten, bei der er sein eigenes Auge opfern muss, um eine Vision des eigenen Todes zu erleben. Ihr könnt nur erahnen, was für ein grausiges Schicksal dieses milchige Auge erblickt hat." }
entries[168303] = { ["name"] = "Zeremonielle Tätowiernadeln", ["text"] = "Wirken in 2 sek. 5\nDiese Knochennadeln stammen von den Leichen gefallener Feinde und wurden sorgfältig geschärft. Die Mystiker des Schattenmondklans versehen ihr Fleisch oftmals mit geheimen Runen, um deutlicher zu ihren Ahnen und den Elementargeistern sprechen zu können." }
entries[168304] = { ["name"] = "Gesprungener Elfenbeingötze", ["text"] = "Wirken in 2 sek. 5\nDieser Götze, so schwarz wie die Nacht, ist ein Beispiel für die Verehrung der Leere, die einst praktiziert wurde, doch heute von den Ältesten des Schattenmondklans untersagt ist. Der Götze wurde grob und unsorgfältig aus dem Hauer eines offenbar riesigen Elekks gehauen. Danach wurde er gefärbt und mit komplexen Spiralen- und Zackenmustern verschönert." }
entries[168305] = { ["name"] = "Ahnentalisman", ["text"] = "Wirken in 2 sek. 5\nDer Rat der Geister der vorangegangenen Generationen wird von den Schamanen des Schattenmondklans bei jeder anstehenden wichtigen Entscheidung als unerlässlich betrachtet. Talismane und andere Relikte, die einem Ahnen zu Lebzeiten wichtig waren, sorgen für eine klarere spirituelle Verbindung, durch die die Schamanen mit ihnen im Jenseits sprechen können." }
entries[168306] = { ["name"] = "Brandfettfläschchen", ["text"] = "Wirken in 2 sek. 5\nDie Substanz in diesem Behälter ist klebrig, übelriechend und ausgesprochen leicht entzündlich. Sie wird vor der Schlacht großzügig auf die Schwerter und Äxte des Klans der Brennenden Klinge aufgetragen. Zwar entscheiden sich einige Krieger dafür, ihre Waffen vor dem Kampf zu entzünden, doch die meisten überlassen es dem unvermeidlichen Kontakt zwischen Klingen und Rüstungen, das Brandfett zu entzünden und ihre Feinde einzuschüchtern." }
entries[168307] = { ["name"] = "Gronnzahnhalskette", ["text"] = "Wirken in 2 sek. 5\nDie Donnerfürsten sind die größten Großwildjäger auf ganz Draenor. Seit Jahrhunderten nutzen sie Reittiere und koordinierte Angriffe, um Gronn und Wildtiere gleichermaßen zur Strecke zu bringen. Der Name ihres Klans rührt von einem uralten Häuptling her, der eigenhändig einen mächtigen Gronn auf der Spitze des Donnergipfels erschlug." }
entries[168308] = { ["name"] = "Weltuntergangsprophezeiung", ["text"] = "Wirken in 2 sek. 5\nDiese Tafel berichtet von der \"Endzeit\". Nach dem zu urteilen, was Ihr entziffern könnt, berichtet das primitive Gekritzel mehrerer Autoren von mindestens sieben verschiedenen, sich manchmal sogar widersprechenden Versionen eines letzten Gerichts für alle Bewohner Draenors. Unheimlich ist dabei, dass die Ikonografie eines brennenden Hammers deutlich dargestellt ist. Handelt es sich hierbei vielleicht um die ersten Anfänge des Schattenhammerklans?" }
entries[168309] = { ["name"] = "Nachfolgestein des Steinbrecherklans", ["text"] = "Wirken in 2 sek. 5\nHäuptlinge herrschen mit eiserner Faust über kleine Gruppen von Ogern und es mangelt ihnen niemals an Herausforderern. Der Steinbrecherklan ist dabei berüchtigt für die hohe Fluktuationsrate seiner Anführer. Nach den Blutschichten auf diesem Stein zu urteilen scheint er eine wichtige Rolle bei der Absetzung mehrere Häuptlinge der Steinbrecher gespielt zu haben." }
entries[168310] = { ["name"] = "Steinfesseln", ["text"] = "Wirken in 2 sek. 5\nStatt mit Schlössern und Haken werden die Sklaven der Oger mit ungebrochenen Steinringen gefesselt. Die jahrhundertelange Manipulation der Erdelemente ermöglicht es ihnen, die Fesseln einfach fest um die Knöchel, Handgelenke oder den Hals des Sklaven schrumpfen lassen." }
entries[168311] = { ["name"] = "Ogerstatuette", ["text"] = "Wirken in 2 sek. 5\nDiese Statue drückt als Skulptur aus, was vielen Ogern mit Worten zu bezeichnen schwer fiele, denn sie fasst das wichtigste körperliche Merkmal der Oger zusammen: die Größe. Der über den Kopf des Oger emporgereckte Grollhuf steht für Stärke, während die kräftige Taille großen Reichtum symbolisiert." }
entries[168312] = { ["name"] = "Geschnitztes Piktogramm", ["text"] = "Wirken in 2 sek. 5\nZwar wird das geschriebene Wort als Werkzeug vor allem von den oberen Schichten der imperialen Ogergesellschaft genutzt, doch gelegentlich versucht auch ein gewöhnlicher Oger sich daran, eine Geschichte unsterblich zu machen. Dieses Piktogramm scheint dabei von einer besonders erschütternden kulinarischen Erfahrung zu berichten." }
entries[168313] = { ["name"] = "Gladiatorenschild", ["text"] = "Wirken in 2 sek. 5\nMeinungsverschiedenheiten zwischen Ogern enden normalerweise in Gewalt. Während der frühen Jahrzehnte des Zeitalters der Ordnung bestimmte ein gerissener Häuptling, dass die Streitigkeiten seines Klans mithilfe von Stellvertretern in Zweikämpfen zwischen Sklaven entschieden werden würden. Die Sterblichkeitsrate unter den Ogern ging zurück und ein goldenes Zeitalter der Expansion brach an." }
entries[168314] = { ["name"] = "Mörser und Stößel", ["text"] = "Wirken in 2 sek. 5\nDa Oger es vorziehen, ihren Körperbau zur Schau zu stellen, meiden sie Kleidung, die zu viel Haut bedeckt. Um ihren Feinden gegenüber noch Furcht einflößender zu erscheinen, verzieren sie ihre Körper mit Kriegsbemalungen, die sie mit solchen Mahlwerkzeugen herstellen. Mörser und Stößel sind gelb verfärbt, was darauf hindeutet, dass sie vom Klan der Felsfäuste benutzt wurden.\nWird beim Aufheben gebunden\nBenutzen: Verpackt das restaurierte Artefakt vorsichtig.\n\"Die Einzelheiten dieses Artefakts wurden bereits in Eurem Archäologiebuch unter 'Restaurierte Artefakte' protokolliert.\"" }
entries[168315] = { ["name"] = "Auge von Har'gunn dem Blinden", ["text"] = "Wirken in 2 sek. 5\nZwar werden die meisten Oger mit zwei Augen geboren, doch in jeder Generation gibt es eine Handvoll von ihnen, die sich zurückentwickeln und mit nur einem Auge geboren werden. Bis auf einige wenige Klans erkennen alle diese Oger als außergewöhnlich und für große Dinge ausersehen an. Ein glückloser einäugiger Ogermagier verlor sein Auge in einem Duell und ersetzte es durch diesen faustgroßen Stein, wobei er entdeckte, dass dieser über magische Eigenschaften verfügte." }
entries[168316] = { ["name"] = "Steingebiss", ["text"] = "Wirken in 2 sek. 5\nOger sind im Kampf recht direkt und stecken oftmals ebenso viel ein, wie sie austeilen. Sie verlassen sich zumeist auf ihre Ausdauer und Kraft. Dieser mit gezackten Zähnen versehene Zahnersatz ist der Beweis dafür, dass mindestens einem Oger all seine Zähne ausgeschlagen wurden und er es überlebte, um ein andermal erneut in den Kampf zu ziehen." }
entries[168317] = { ["name"] = "Rylakzaumzeug", ["text"] = "Wirken in 2 sek. 5\nEin genialer Oger kam einst zu der Einsicht, dass es das Reisen ungemein beschleunigen würde, wenn man auf einem Rylak anstelle eines Lasttiers reiten oder gar zu Fuß gehen würde. Dieser aus dickem Leder grob zusammengeflickte und mit vielen Knoten versehene Sattel dient einem Oger als bequeme Sitzmöglichkeit. Allerdings passt er nur auf einen Rylak in Größe eines kleinen Berges. Möglicherweise ist dies der Grund, warum man noch nie einen Oger hat fliegen sehen." }
entries[168318] = { ["name"] = "Imperiale Verordnungsstele", ["text"] = "Wirken in 2 sek. 5\nDie zusammengesetzten Bruchstücke dieser steinernen Stele lassen sich mehrere hundert Jahre vor der Ankunft der Draenei in Talador verorten. Die Stele markiert ein imperiales Dekret der Oger, mehrere Orcniederlassungen als Vergeltung für eine Reihe rebellischer Überfälle auf gorianische Sklavenhandelskarawanen durchzuführen. Die Befehle wurden höchstwahrscheinlich ausgeführt, denn die Städte existieren nicht mehr, und diese Stele wurde errichtet, um der finsteren Tat zu gedenken." }
entries[168319] = { ["name"] = "Zehenring des Zaubererkönigs", ["text"] = "Wirken in 2 sek. 10\nImperiale Oger wachen eifersüchtig über die Geheimnisse der Magie, um sich ihren Status in der Herrscherschicht zu wahren. Die Wohlhabendsten unter ihnen schmücken sich mit magisch verstärktem Schmuck und anderen tragbaren Artefakten.\nZehenring des Zaubererkönigs\nWird an Kriegsmeute gebunden\nHals\n+3 Intelligenz\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 2.\n35" }
entries[168320] = { ["name"] = "Totschläger des Totschlägerhäuptlings", ["text"] = "Wirken in 2 sek. 10\nDie erste große technologische Innovation in der Gesellschaft der Oger war das Konzept, einen Stein am Ende eines sehr langen Stocks zu befestigen, um damit auf seine Feinde einzuprügeln, statt einfach mit dem Stein in der Faust zuzuschlagen. Die Spaltung, die diese Innovation in der Gesellschaft der Oger nach sich zog, löste sich erst, als der heute in Vergessenheit geratene Stamm in die Klans der Totschläger und der Felsfäuste zerbrach.\nTotschläger des Totschlägerhäuptlings\nWird an Kriegsmeute gebunden\nZweihändig Streitkolben\n10 - 14 Schaden Geschwindigkeit 3.60\n(3.3 Schaden pro Sekunde)\n+5 Stärke\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 100 / 100\n35" }
entries[168321] = { ["name"] = "Traumfänger", ["text"] = "Wirken in 2 sek. 5\nAls Terokk aus dem Exil zurückkehrte, war er gebrochen und flugunfähig. Gerüchte über seinen verfluchten Zustand verbreiteten sich wie ein Lauffeuer unter den Arakkoa und waren Anlass zur Verbreitung abergläubischer Amulette und Heilmittel. Traumfänger haben sich als eine der hartnäckigsten Ikonen des Schutzes gehalten, denn die Arakkoa glauben, dass der Fluch sich im Traumfänger verheddern und im morgendlichen Sonnenlicht verblassen werde." }
entries[168322] = { ["name"] = "Begräbnisurne", ["text"] = "Wirken in 2 sek. 5\nIm Tod streben alle Arakkoa danach, an die Seite der Sonnengöttin Rukhmar im Himmel über Draenor zu gelangen, daher ziehen sie eine Feuerbestattung dem Begräbnis vor. Manche von ihnen lassen ihre Asche hoch am Himmel verstreuen, während die Überreste anderer in reich verzierten Urnen in Krypten aufbewahrt werden." }
entries[168323] = { ["name"] = "Dekretschriftrollen", ["text"] = "Wirken in 2 sek. 5\nDiese unvollständigen Aufzeichnungen scheinen einen Erlass für eine Art Kriegsrecht darzustellen und rufen dazu auf, bei Nachbarn und Freunden wachsam auf Anzeichen des Fluches zu achten." }
entries[168324] = { ["name"] = "Sonnenkugel", ["text"] = "Wirken in 2 sek. 5\nIm Mittelpunkt der Kultur der Hocharakkoa steht die Anbetung von Rukhmar und der Sonne. Hunderte von Sonnenkugeln finden sich um die Himmelsnadel verteilt. Sie sorgen für ein ewig scheinendes Licht, damit kein Arakkoa auf die Wärme der Sonne verzichten muss, nicht einmal an kalten und bewölkten Tagen." }
entries[168325] = { ["name"] = "Sonnenuhr", ["text"] = "Wirken in 2 sek. 5\nDieses fein gravierte Instrument fungiert, wenn es richtig aufgestellt wird, sowohl als Sonnenuhr als auch als Jahreszeitenkalender für die Arakkoa. Die Basis des Instruments ist mit Angaben zu Himmelsereignissen versehen. Die meisten werden von düsteren Warnungen begleitet. Interessanterweise scheint das Gerät auf kryptische Weise die Ankunft der Draenei etwa ein Jahrhundert vor dem Ereignis vorhergesagt zu haben." }
entries[168326] = { ["name"] = "Krallenpriestermaske", ["text"] = "Wirken in 2 sek. 5\nDa sie glauben, die Sonne hätte sie im Stich gelassen, ziehen es die verfluchten Arakkoa vor, sich während der Tagesstunden in den Wäldern oder unter einem Sonnenschutz zu verstecken. Krallenpriester gehen sogar noch einen Schritt weiter und zeigen ihr Gesicht niemals der Sonne. Vielmehr tragen sie rituelle Masken, die als Fokus für ihre Kommunion mit Anzu dienen." }
entries[168327] = { ["name"] = "Traumfänger der Ausgestoßenen", ["text"] = "Wirken in 2 sek. 5\nAusgestoßene Arakkoa haben den Traumfänger umfunktioniert. Für sie wehrt er nicht mehr Sethes Fluch ab, sondern dient dazu, winzige Mengen der Essenz ihrer verlorenen Götter einzufangen und sie zu sammeln. Es halten sich Gerüchte über eine stetig wachsende Masse wirbelnder Energie, die unter Skettis vergraben liegt und die all jenen, die zuhören, Versprechen von Macht ins Ohr flüstert." }
entries[168328] = { ["name"] = "Apexiskristall", ["text"] = "Wirken in 2 sek. 5\nÜber die ältesten Ruinen auf Draenor verstreut finden sich Fragmente und geisterhafte Hinweise auf die Zivilisation der Apexis, die ihren Höhepunkt im Zeitalter der Ordnung erlangte und dann abrupt verschwand. Seit der Ankunft der Eisernen Horde haben die Jünger ihre geheime Suche nach Apexisartefakten verstärkt." }
entries[168329] = { ["name"] = "Apexishieroglyphe", ["text"] = "Wirken in 2 sek. 5\nDiese Steintafel ist brüchig und über alle Maßen alt. Sie enthält Gravuren, die vage eine Maschine von unglaublicher Macht beschreiben, die sich angeblich die Kraft der Sonne zunutze macht." }
entries[168330] = { ["name"] = "Apexisschriftrolle", ["text"] = "Wirken in 2 sek. 5\nDieser ramponierte Schriftrollenbehälter ist zugerostet und die Schriftrolle in seinem Innern bei vorsichtiger Untersuchung kaum lesbar. Es scheint sich dabei um die Pläne und Abmessungen für einen prunkvollen \"Himmelstempel\" zu handeln, die in einer uralten Schrift verfasst wurden. Es ist unklar, ob ein derart prächtiges Gebäude je errichtet wurde." }
entries[168331] = { ["name"] = "Schnabelbrecher von Terokk", ["text"] = "Wirken in 2 sek. 10\nTerokk, der die traditionellen Waffen der Arakkoa mied, trug seinen Knüppel als Symbol seines Sturzes vom König zum ausgestoßenen Ketzer. Jahrhundertelang hielten sich Gerüchte, dass Terokk, anstatt auf die traditionelle Bestrafungsmethode des Flügelstutzens zurückzugreifen, einfach die Schnäbel jener zerschmetterte, die sich ihm entgegenstellten.\nSchnabelbrecher von Terokk\nWird an Kriegsmeute gebunden\nEinhändig Streitkolben\n5 - 7 Schaden Geschwindigkeit 2.60\n(2.3 Schaden pro Sekunde)\n+2 [Beweglichkeit oder Stärke]+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 90 / 90\n35" }
